#!/usr/bin/env node
// Builds data/cctv/generated/freewayCctvInventory.js from the official
// 交通部高速公路局 (NFB) static CCTV inventory XML.
//
// Run:  node scripts/build-cctv-inventory.mjs [path-to-CCTV_v2.0_*.xml]
//
// With no argument it rebuilds from the committed official source at
// data/cctv/raw/CCTV_v2.0_freeway.xml, so the generated artifact is
// reproducible byte-for-byte by anyone with the repo and nothing else.
// Pass a path to refresh from a newer download from the NFB open-data site.
//
// Same shape and discipline as data/road-location/generated/* — a bundled,
// auto-generated, regenerable artifact, never hand-edited. It exists so the
// broadcast path has a camera inventory that does not depend on TDX being
// switched on: see src/cctv/freewayCctvMetadataCache.js for how it is used.
//
// Verifies before writing, and refuses to emit an inventory that would be a
// downgrade: zero records, no 國道1號, no 國道3號, or nothing near 國1 93K
// (the exact incident that exposed the deadlock) all abort the build.

import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { parseNfbCctvXml } from './lib/nfbCctvXml.mjs';

const OUT_PATH = 'data/cctv/generated/freewayCctvInventory.js';
const DEFAULT_SOURCE = 'data/cctv/raw/CCTV_v2.0_freeway.xml';

function parseMile(mile) {
  const m = String(mile).match(/(\d+(?:\.\d+)?)\s*K(?:\s*\+\s*(\d{1,3}))?/i);
  if (!m) return null;
  return parseFloat(m[1]) + (m[2] ? parseInt(m[2], 10) / 1000 : 0);
}

async function main() {
  const source = process.argv[2] || DEFAULT_SOURCE;

  let xml;
  try {
    xml = await readFile(source, 'utf8');
  } catch {
    console.error(`cannot read ${source}`);
    console.error('usage: node scripts/build-cctv-inventory.mjs [path-to-CCTV_v2.0_*.xml]');
    process.exit(1);
  }
  const { metadata, records, skipped } = parseNfbCctvXml(xml);

  const n1 = records.filter((r) => r.RoadID === '000010');
  const n3 = records.filter((r) => r.RoadID === '000030');
  const near93 = n1.filter((r) => {
    const km = parseMile(r.LocationMile);
    return km !== null && Math.abs(km - 93) <= 3;
  });
  const withUrl = records.filter((r) => typeof r.VideoStreamURL === 'string' && r.VideoStreamURL.length > 0);
  const parseableMile = records.filter((r) => parseMile(r.LocationMile) !== null);

  const checks = [
    ['records > 0', records.length > 0],
    ['國道1號 records > 0', n1.length > 0],
    ['國道3號 records > 0', n3.length > 0],
    ['國1 93K±3 records > 0', near93.length > 0],
    ['every record has a VideoStreamURL', withUrl.length === records.length],
    ['every LocationMile parses', parseableMile.length === records.length],
  ];
  for (const [label, ok] of checks) console.log(`${ok ? '✅' : '❌'} ${label}`);
  if (checks.some(([, ok]) => !ok)) {
    console.error('refusing to write an inventory that fails its own checks');
    process.exit(1);
  }

  const sha256 = createHash('sha256').update(xml).digest('hex');
  const payload = {
    metadata: {
      sourceName: '即時交通資訊 CCTV 靜態資料 (CCTV_v2.0)',
      sourceAgency: '交通部高速公路局 (NFB)',
      authorityCode: metadata.authorityCode,
      sourceUpdatedAt: metadata.updateTime,
      linkVersion: metadata.linkVersion,
      sourceFile: path.basename(source),
      sourceSha256: sha256,
      recordCount: records.length,
      skippedRecordCount: skipped,
      note:
        'Auto-generated by scripts/build-cctv-inventory.mjs from the official NFB open-data file. ' +
        'Field names are preserved verbatim so tdx/hsinchuCctvProbe.js reads it exactly as it reads a ' +
        'live TDX response. Zero TDX calls were made to produce it.',
    },
    records,
  };

  await mkdir(path.dirname(OUT_PATH), { recursive: true });
  await writeFile(
    OUT_PATH,
    '// AUTO-GENERATED by scripts/build-cctv-inventory.mjs — do not hand-edit.\n' +
      '// Regenerate with: node scripts/build-cctv-inventory.mjs <CCTV_v2.0_*.xml>\n' +
      '// Source: 交通部高速公路局 official open data. Produced with ZERO TDX calls.\n' +
      `export default ${JSON.stringify(payload, null, 2)};\n`,
    'utf8'
  );

  console.log(`\n✅ wrote ${OUT_PATH}`);
  console.log(`   records: ${records.length} (skipped ${skipped})`);
  console.log(`   國道1號: ${n1.length} | 國道3號: ${n3.length} | 國1 93K±3: ${near93.length}`);
  console.log(`   source updated at: ${metadata.updateTime}`);
}

main();
